sys_properties.value:
[
    {
        "label": "Is your organization's procurement system currently active?",
        "name": "u_procurement_system",
        "type": "radio",
        "options": ["Enabled", "Disabled"],
        "conditional": {
            "showOn": "Enabled",
            "field": "u_name_of_the_procurement_system",
            "label": "Name of the Procurement System",
            "type": "text"
        }
    },
    {
        "label": "Has your organization implemented cloud discovery capabilities?",
        "name": "u_cloud_discovery",
        "type": "radio",
        "options": ["Enabled", "Disabled"]
    },
   
    {
        "label": "Does your organization utilize third-party software for employee onboarding and offboarding processes?",
        "name": "u_third_party_software",
        "type": "radio",
        "options": ["Yes", "No"],
        "conditional": {
            "showOn": "Yes",
            "field": "u_third_party_software_name",
            "label": "3rd Party Software Name",
            "type": "text"
        }
    },
    {
        "label": "Is client software distribution capability available within your organization?",
        "name": "u_client_software",
        "type": "radio",
        "options": ["Available", "Not Available"],
        "conditional": {
            "showOn": "Available",
            "field": "u_integration_type",
            "label": "Type of Integration",
            "type": "text"
        }
    }
]
